#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        int temp;
        cin >> temp;
        a[i] = temp % m;
    }

    set<int> set1, set2;

    function<void(set<int>&, int, int, int)> build_subsets = [&](set<int>& subset_set, int length, int start_index, int total=0) {
        if (start_index == length) {
            subset_set.insert(total);
        } else {
            build_subsets(subset_set, length, start_index + 1, (total + a[start_index]) % m);
            build_subsets(subset_set, length, start_index + 1, total);
        }
    };

    int mid = n / 2;
    build_subsets(set1, mid, 0);
    build_subsets(set2, n, mid);

    vector<int> sorted_set2(set2.begin(), set2.end());
    sort(sorted_set2.begin(), sorted_set2.end());

    int max_sum = 0;
    for (int val : set1) {
        int idx = (int)(std::lower_bound(sorted_set2.begin(), sorted_set2.end(), m - val) - sorted_set2.begin());
        if (idx > 0) {
            int candidate_sum = val + sorted_set2[idx - 1];
            if (candidate_sum > max_sum) {
                max_sum = candidate_sum;
            }
        }
    }
    cout << max_sum << "\n";

    return 0;
}
